=== FILE: tick_timer_cov_tb.sv ===
// Coverage testbench for tick_timer.v (W=16). Extends the approved idle
// testbench: one-shot and periodic counting, expiry, W1C clear, the
// expiry-wins-over-clear collision, CTRL-write expiry suppression, stop/hold,
// full-width LOAD/wdata toggles, a full 16-bit count-down and a second reset.
// Every expected value is a fixed cycle-exact check.
`timescale 1ns / 1ps
module tick_timer_cov_tb;
    logic        clk = 1'b0;
    logic        rst_n = 1'b0;
    logic        we = 1'b0;
    logic [1:0]  addr = 2'd0;
    logic [31:0] wdata = 32'd0;
    logic [31:0] rdata;
    logic        irq;
    int checks = 0, errors = 0;
    logic [8*64-1:0] nonce;

    tick_timer #(.W(16)) dut (.clk(clk), .rst_n(rst_n), .we(we), .addr(addr), .wdata(wdata), .rdata(rdata), .irq(irq));
    always #5 clk = ~clk;

    task automatic expect_reg(input logic [1:0] a, input logic [31:0] expected);
        addr = a;
        #1;
        checks++;
        if (rdata !== expected) begin
            errors++;
            $display("ERROR t=%0t addr=%0d rdata=%h expected=%h", $time, a, rdata, expected);
        end
    endtask

    task automatic expect_irq(input logic expected);
        checks++;
        if (irq !== expected) begin
            errors++;
            $display("ERROR t=%0t irq=%b expected=%b", $time, irq, expected);
        end
    endtask

    task automatic write(input logic [1:0] a, input logic [31:0] d);
        we = 1'b1; addr = a; wdata = d;
        @(posedge clk); #1;
        we = 1'b0; wdata = 32'd0;
    endtask

    task automatic tick(input int n);
        repeat (n) @(posedge clk);
        #1;
    endtask

    initial begin
        repeat (3) @(posedge clk);
        #1 rst_n = 1'b1;
        tick(1);
        // Reset values
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        // One-shot from 3 with IE
        write(2'd1, 32'd3);
        expect_reg(2'd1, 32'd3);
        write(2'd0, 32'h5);
        expect_reg(2'd0, 32'h5);
        expect_reg(2'd2, 32'd3);
        tick(1);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd0);
        tick(2);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd0, 32'h5);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);
        tick(1);
        expect_reg(2'd0, 32'h4);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b1);
        expect_reg(2'd2, 32'd0);
        tick(2);
        expect_reg(2'd0, 32'h4);
        expect_reg(2'd3, 32'd1);
        write(2'd3, 32'd0);
        expect_reg(2'd3, 32'd1);
        write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        // Periodic from 2 without IE
        write(2'd1, 32'd2);
        write(2'd0, 32'h3);
        expect_reg(2'd0, 32'h3);
        expect_reg(2'd2, 32'd2);
        tick(2);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        tick(1);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b0);
        tick(2);
        expect_reg(2'd2, 32'd0);
        // Clear at an expiry edge: expiry wins
        write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd1);
        expect_reg(2'd2, 32'd2);
        // Clear at a non-expiry edge
        write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);
        expect_reg(2'd2, 32'd1);
        tick(1);
        expect_reg(2'd2, 32'd0);
        // CTRL write while running at zero: expiry suppressed, no reload
        write(2'd0, 32'h3);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_reg(2'd0, 32'h3);
        tick(1);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd1);
        // Stop: count holds
        write(2'd0, 32'h0);
        expect_reg(2'd0, 32'h0);
        expect_reg(2'd2, 32'd2);
        expect_reg(2'd3, 32'd1);
        tick(3);
        expect_reg(2'd2, 32'd2);
        write(2'd3, 32'd1);
        expect_reg(2'd3, 32'd0);

        // Full width: all-ones wdata, LOAD 16'hFFFF, full count-down
        write(2'd1, 32'hFFFF_FFFF);
        expect_reg(2'd1, 32'h0000_FFFF);
        write(2'd0, 32'hFFFF_FFFF);
        expect_reg(2'd0, 32'h7);
        expect_reg(2'd2, 32'h0000_FFFF);
        tick(1);
        expect_reg(2'd2, 32'h0000_FFFE);
        tick(65534);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);
        tick(1);
        expect_reg(2'd2, 32'h0000_FFFF);
        expect_reg(2'd3, 32'd1);
        expect_irq(1'b1);
        write(2'd0, 32'h6);
        expect_reg(2'd0, 32'h6);
        expect_reg(2'd2, 32'h0000_FFFF);
        expect_irq(1'b1);
        write(2'd1, 32'd0);
        expect_reg(2'd1, 32'd0);
        // Start one-shot from LOAD 0: expires at the next edge
        write(2'd0, 32'h1);
        expect_reg(2'd0, 32'h1);
        expect_reg(2'd2, 32'd0);
        expect_irq(1'b0);
        tick(1);
        expect_reg(2'd0, 32'h0);
        expect_reg(2'd3, 32'd1);
        write(2'd3, 32'hFFFF_FFFF);
        expect_reg(2'd3, 32'd0);

        // Second reset while running
        write(2'd1, 32'h0000_1234);
        write(2'd0, 32'h7);
        expect_reg(2'd2, 32'h0000_1234);
        rst_n = 1'b0;
        tick(2);
        rst_n = 1'b1;
        tick(1);
        expect_reg(2'd0, 32'd0);
        expect_reg(2'd1, 32'd0);
        expect_reg(2'd2, 32'd0);
        expect_reg(2'd3, 32'd0);
        expect_irq(1'b0);

        if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = "none";
        $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, (checks > errors ? checks - errors : 0), errors);
        $finish;
    end
endmodule
=== END FILE ===
